export function posComparison(start,end,a){
 const days=[];for(let d=start;d<=end;){days.push(d);d=new Date(new Date(d+'T00:00:00Z').getTime()+86400000).toISOString().slice(0,10);if(days.length>1500)break}
 const previous=days.map(d=>{const x=new Date(d+'T00:00:00Z');x.setUTCFullYear(x.getUTCFullYear()-1);return x.toISOString().slice(5,10)===d.slice(5)?x.toISOString().slice(0,10):null});
 const coverage=new Set(a.productCoverage),partial=new Set(a.partialProductDates||[]),sums=new Map();for(const r of a.products)sums.set(r.date,(sums.get(r.date)||0)+r.sales);
 const stat=ds=>({total:ds.reduce((s,d)=>s+(sums.get(d)||0),0),count:ds.filter(d=>coverage.has(d)&&!partial.has(d)).length,complete:ds.length>0&&ds.every(d=>d&&coverage.has(d)&&!partial.has(d))});return {current:stat(days),previous:stat(previous),days:days.length,start,end,priorStart:previous[0],priorEnd:previous.at(-1)};
}
export function renderPosComparison(start,end,a,{won}){const x=posComparison(start,end,a),ok=x.current.complete&&x.previous.complete,delta=x.current.total-x.previous.total;return `<section class="card pos-year-comparison" style="margin:20px 0"><div class="card-head"><div><h3>전년 대비 · 동일 POS 원본 기준</h3><p class="sub">${start} ~ ${end} ↔ ${x.priorStart||'해당일 없음'} ~ ${x.priorEnd||'해당일 없음'} · 같은 날짜 비교</p></div><span class="badge">2025년 자료 연결</span></div><div class="detail-kpis"><article class="detail-kpi"><span>선택 기간 POS 실매출</span><strong>${x.current.count?won(x.current.total):'POS 원본 없음'}</strong><small>${x.current.count}/${x.days}일 확인</small></article><article class="detail-kpi"><span>전년 같은 기간 POS 실매출</span><strong>${x.previous.count?won(x.previous.total):'전년 POS 원본 없음'}</strong><small>${x.previous.count}/${x.days}일 확인</small></article><article class="detail-kpi"><span>POS 전년 대비</span><strong>${ok?(delta<0?'−':'+')+won(Math.abs(delta)):'비교 기간 원본 부족'}</strong><small>${ok?(x.previous.total?(delta/x.previous.total*100).toFixed(1)+'%':'전년 0원 · 증감률 미산출'):`선택 ${x.current.count}/${x.days}일 · 전년 ${x.previous.count}/${x.days}일`}</small></article></div><p class="sub">제공된 2025·2026 POS 상품 실매출 전체를 같은 범위로 비교합니다. POS에 기록된 배달앱 항목도 양쪽 원본에 포함하며, 별도 오터·네이버 금액을 더하지 않습니다. 전 채널 총매출의 전년 대비와 구분합니다.</p></section>`}
